create or replace function public.approve_itacash_purchase_request_v2(p_request_id uuid, p_admin_id uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_request record; v_wallet record; v_balance_after integer; begin select * into v_request from public.itacash_purchase_requests where id = p_request_id for update; if v_request.id is null then raise exception 'Solicitação de compra não encontrada.'; end if; if v_request.status <> 'pending' then return jsonb_build_object('success', false, 'reason', 'already_processed', 'status', v_request.status); end if; update public.itacash_purchase_requests set status = 'approved', reviewed_at = now(), reviewed_by = p_admin_id, updated_at = now() where id = p_request_id; insert into public.itacash_wallets (user_id) values (v_request.user_id) on conflict (user_id) do nothing; select * into v_wallet from public.itacash_wallets where user_id = v_request.user_id for update; v_balance_after := v_wallet.balance + v_request.amount_itacash; update public.itacash_wallets set balance = v_balance_after, updated_at = now() where id = v_wallet.id; insert into public.itacash_transactions (wallet_id, user_id, type, amount, balance_after, description, reference_type, reference_id) values (v_wallet.id, v_request.user_id, 'purchase_confirmed', v_request.amount_itacash, v_balance_after, 'Compra manual de ItaCash aprovada pelo administrador', 'payment_order', v_request.id); insert into public.notifications (user_id, actor_id, type, amount) values (v_request.user_id, v_request.user_id, 'itacash_purchase_approved', v_request.amount_itacash); return jsonb_build_object('success', true, 'status', 'approved', 'balance_after', v_balance_after); end; $$; create or replace function public.reject_itacash_purchase_request_v2(p_request_id uuid, p_admin_id uuid, p_rejection_reason text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_request record; begin select * into v_request from public.itacash_purchase_requests where id = p_request_id for update; if v_request.id is null then raise exception 'Solicitação de compra não encontrada.'; end if; if v_request.status <> 'pending' then return jsonb_build_object('success', false, 'reason', 'already_processed', 'status', v_request.status); end if; update public.itacash_purchase_requests set status = 'rejected', rejection_reason = p_rejection_reason, reviewed_at = now(), reviewed_by = p_admin_id, updated_at = now() where id = p_request_id; insert into public.notifications (user_id, actor_id, type, amount) values (v_request.user_id, v_request.user_id, 'itacash_purchase_rejected', v_request.amount_itacash); return jsonb_build_object('success', true, 'status', 'rejected'); end; $$;
